    [10,284,"ויארכו הבדים ויראו ראשי הבדים מן הקדש על פני הדביר ולא יראו החוצה ויהיו שם עד היום הזה"],
    [10,285,"אין בארון רק שני לחות האבנים אשר הנח שם משה בחרב אשר כרת ה׳ עם בני ישראל בצאתם מארץ מצרים"],
    [10,286,"ויהי בצאת הכהנים מן הקדש והענן מלא את בית ה׳"],
    [10,287,"ולא יכלו הכהנים לעמד לשרת מפני הענן כי מלא כבוד ה׳ את בית ה׳"],
    [10,330,"ויהי ככלות שלמה להתפלל אל ה׳ את כל התפלה והתחנה הזאת קם מלפני מזבח ה׳ מכרע על ברכיו וכפיו פרשות השמים"],
    [10,340,"ביום ההוא קדש המלך את תוך החצר אשר לפני בית ה׳ כי עשה שם את העלה ואת המנחה ואת חלבי השלמים כי מזבח הנחשת אשר לפני ה׳ קטן מהכיל את העלה ואת המנחה ואת חלבי השלמים"],
    [10,341,"ויעש שלמה בעת ההיא את החג וכל ישראל עמו קהל גדול מלבוא חמת עד נחל מצרים לפני ה׳ אלהינו שבעת ימים ושבעת ימים ארבעה עשר יום"],
    [10,377,"ומאכל שלחנו ומושב עבדיו ומעמד משרתו ומלבשיהם ומשקיו ועלתו אשר יעלה בית ה׳ ולא היה בה עוד רוח"],
    [10,388,"ויעש המלך שלמה מאתים צנה זהב שחוט שש מאות זהב יעלה על הצנה האחת"],
    [10,389,"ושלש מאות מגנים זהב שחוט שלשת מנים זהב יעלה על המגן האחת ויתנם המלך בית יער הלבנון"],
    [10,390,"ויעש המלך כסא שן גדול ויצפהו זהב מופז"],
    [10,391,"שש מעלות לכסה וראש עגל לכסה מאחריו וידת מזה ומזה אל מקום השבת ושנים אריות עמדים אצל הידות"],
    [10,392,"ושנים עשר אריים עמדים שם על שש המעלות מזה ומזה לא נעשה כן לכל ממלכות"],
    [10,393,"וכל כלי משקה המלך שלמה זהב וכל כלי בית יער הלבנון זהב סגור אין כסף לא נחשב בימי שלמה למאומה"],
    [39,39,"ויחל שלמה לבנות את בית ה׳ בירושלם בהר המוריה אשר נראה לדויד אביהו אשר הכין במקום דויד בגרן ארנן היבוסי"],
    [39,40,"ויחל לבנות בחדש השני בשני בשנת ארבע למלכותו"],
    [39,41,"ואלה הוסד שלמה לבנות את בית האלהים הארך אמות במדה הראשונה אמות ששים ורחב אמות עשרים"],
    [39,42,"והאולם אשר על פני הארך על פני רחב הבית אמות עשרים והגבה מאה ועשרים ויצפהו מפנימה זהב טהור"],
    [39,43,"ואת הבית הגדול חפה עץ ברושים ויחפהו זהב טוב ויעל עליו תמרים ושרשרת"],
    [39,44,"ויצף את הבית אבן יקרה לתפארת והזהב זהב פרוים"],
    [39,45,"ויחף את הבית הקרות הספים וקירותיו ודלתותיו זהב ופתח כרובים על הקירות"],
    [39,46,"ויעש את בית קדש הקדשים ארכו על פני רחב הבית אמות עשרים ורחבו אמות עשרים ויחפהו זהב טוב לככרים שש מאות"],
    [39,47,"ומשקל למסמרות לשקלים חמשים זהב והעליות חפה זהב"],
    [39,48,"ויעש בבית קדש הקדשים כרובים שנים מעשה צעצעים ויצפו אתם זהב"],
    [39,49,"וכנפי הכרובים ארכם אמות עשרים כנף האחד לאמות חמש מגעת לקיר הבית והכנף האחרת אמות חמש מגיע לכנף הכרוב האחר"],
    [39,50,"וכנף הכרוב האחד אמות חמש מגיע לקיר הבית והכנף האחרת אמות חמש דבקה לכנף הכרוב האחר"],
    [39,51,"כנפי הכרובים האלה פרשים אמות עשרים והם עמדים על רגליהם ופניהם לבית"],
    [39,52,"ויעש את הפרכת תכלת וארגמן וכרמיל ובוץ ויעל עליו כרובים"],
    [39,53,"ויעש לפני הבית עמודים שנים אמות שלשים וחמש ארך והצפת אשר על ראשו אמות חמש"],
    [39,54,"ויעש שרשרות בדביר ויתן על ראש העמדים ויעש רמונים מאה ויתן בשרשרות"],
    [39,55,"ויקם את העמודים על פני ההיכל אחד מימין ואחד מהשמאול ויקרא שם [הימני] (הימיני) יכין ושם השמאלי בעז"],
    [39,57,"ויעש מזבח נחשת עשרים אמה ארכו ועשרים אמה רחבו ועשר אמות קומתו"],
    [39,58,"ויעש את הים מוצק עשר באמה משפתו אל שפתו עגול סביב וחמש באמה קומתו וקו שלשים באמה יסב אתו סביב"],
    [39,59,"ודמות בקרים תחת לו סביב סביב סובבים אתו עשר באמה מקיפים את הים סביב שנים טורים הבקר יצוקים במצקתו"],
    [39,60,"עומד על שנים עשר בקר שלשה פנים צפונה ושלושה פנים ימה ושלשה פנים נגבה ושלשה פנים מזרחה והים עליהם מלמעלה וכל אחריהם ביתה"],
    [39,61,"ועביו טפח ושפתו כמעשה שפת כוס פרח שושנה מחזיק בתים שלשת אלפים יכיל"],
    [39,62,"ויעש כיורים עשרה ויתן חמשה מימין וחמשה משמאול לרחצה בהם את מעשה העולה ידיחו בם והים לרחצה לכהנים בו"],
    [39,63,"ויעש את מנרות הזהב עשר כמשפטם ויתן בהיכל חמש מימין וחמש משמאול"],
    [39,64,"ויעש שלחנות עשרה וינח בהיכל חמשה מימין וחמשה משמאול ויעש מזרקי זהב מאה"],
    [39,65,"ויעש חצר הכהנים והעזרה הגדולה ודלתות לעזרה ודלתותיהם צפה נחשת"],
    [39,66,"ואת הים נתן מכתף הימנית קדמה ממול נגבה"],
    [39,67,"ויעש חורם את הסירות ואת היעים ואת המזרקות ויכל (חירם) [חורם] לעשות את המלאכה אשר עשה למלך שלמה בבית האלהים"],
    [39,68,"עמודים שנים והגלות והכתרות על ראש העמודים שתים והשבכות שתים לכסות את שתי גלות הכתרות אשר על ראש העמודים"],
    [39,69,"ואת הרמונים ארבע מאות לשתי השבכות שנים טורים רמונים לשבכה האחת לכסות את שתי גלות הכתרות אשר על פני העמודים"],
    [39,70,"ואת המכנות עשה ואת הכירות עשה על המכנות"],
    [39,71,"את הים אחד ואת הבקר שנים עשר תחתיו"],
    [39,72,"ואת הסירות ואת היעים ואת המזלגות ואת כל כליהם עשה חורם אביו למלך שלמה לבית ה׳ נחשת מרוק"],
    [39,73,"בככר הירדן יצקם המלך בעבי האדמה בין סכות ובין צרדתה"],
    [39,74,"ויעש שלמה כל הכלים האלה לרב מאד כי לא נחקר משקל הנחשת"],
    [39,75,"ויעש שלמה את כל הכלים אשר בית האלהים ואת מזבח הזהב ואת השלחנות ועליהם לחם הפנים"],
    [39,76,"ואת המנרות ונרתיהם לבערם כמשפט לפני הדביר זהב סגור"],
    [39,77,"והפרח והנרות והמלקחים זהב הוא מכלות זהב"],
    [39,78,"והמזמרות והמזרקות והכפות והמחתות זהב סגור ופתח הבית דלתותיו הפנימיות לקדש הקדשים ודלתי הבית להיכל זהב"],
    [39,81,"אז יקהיל שלמה את זקני ישראל ואת כל ראשי המטות נשיאי האבות לבני ישראל אל ירושלם להעלות את ארון ברית ה׳ מעיר דויד היא ציון"],
    [39,82,"ויקהלו אל המלך כל איש ישראל בחג הוא החדש השבעי"],
    [39,83,"ויבאו כל זקני ישראל וישאו הלוים את הארון"],
    [39,84,"ויעלו את הארון ואת אהל מועד ואת כל כלי הקדש אשר באהל העלו אתם הכהנים הלוים"],
    [39,85,"והמלך שלמה וכל עדת ישראל הנועדים עליו לפני הארון מזבחים צאן ובקר אשר לא יספרו ולא ימנו מרב"],
    [39,86,"ויביאו הכהנים את ארון ברית ה׳ אל מקומו אל דביר הבית אל קדש הקדשים אל תחת כנפי הכרובים"],
    [39,87,"ויהיו הכרובים פרשים כנפים על מקום הארון ויכסו הכרובים על הארון ועל בדיו מלמעלה"],
    [39,88,"ויאריכו הבדים ויראו ראשי הבדים מן הארון על פני הדביר ולא יראו החוצה ויהי שם עד היום הזה"],
    [39,89,"אין בארון רק שני הלחות אשר נתן משה בחרב אשר כרת ה׳ עם בני ישראל בצאתם ממצרים"],
    [39,93,"ולא יכלו הכהנים לעמוד לשרת מפני הענן כי מלא כבוד ה׳ את בית האלהים"],
    [39,107,"כי עשה שלמה כיור נחשת ויתנהו בתוך העזרה חמש אמות ארכו וחמש אמות רחבו ואמות שלוש קומתו ויעמד עליו ויברך על ברכיו נגד כל קהל ישראל ויפרש כפיו השמימה"],
    [39,136,"ה׳ אלהים אל תשב פני משיחך זכרה לחסדי דויד עבדך"],
    [39,171,"ואת בת פרעה העלה שלמה מעיר דויד לבית אשר בנה לה כי אמר לא תשב אשה לי בבית דויד מלך ישראל כי קדש המה אשר באה אליהם ארון ה׳"],
    [39,183,"ומאכל שלחנו ומושב עבדיו ומעמד משרתיו ומלבושיהם ומשקיו ומלבושיהם ועליתו אשר יעלה בית ה׳ ולא היה עוד בה רוח"],
    [39,196,"ויעש המלך כסא שן גדול ויצפהו זהב טהור"],
    [39,197,"ושש מעלות לכסא וכבש בזהב לכסא מאחזים וידות מזה ומזה על מקום השבת ושנים אריות עמדים אצל הידות"],
    [39,198,"ושנים עשר אריות עמדים שם על שש המעלות מזה ומזה לא נעשה כן לכל ממלכה"],
    [39,418,"ויעמד יהושפט בקהל יהודה וירושלם בבית ה׳ לפני החצר החדשה"],
    [39,498,"ותרא והנה המלך עומד על עמודו במבוא והשרים והחצצרות על המלך וכל עם הארץ שמח ותוקע בחצצרות והמשוררים בכלי השיר ומודיעים להלל ותקרע עתליהו את בגדיה ותאמר קשר קשר"],
    [39,515,"ויאמר המלך ויעשו ארון אחד ויתנהו בשער בית ה׳ חוצה"],
    [39,633,"גם סגרו דלתות האולם ויכבו את הנרות וקטרת לא הקטירו ועלה לא העלו בקדש לאלהי ישראל"]
